{
  "items": [
    {
      "label": "FIGURE O.3",
      "kind": "chart",
      "title": "Poverty is still above prepandemic levels in the poorest countries",
      "bbox": [
        315,
        165,
        675,
        820
      ],
      "content": {
        "chart_type": "line chart",
        "panels": [
          {
            "title": "a. Poverty at $2.15 relative to 2019 levels",
            "y_axis": "Change in extreme poverty rates (2019 = 1)",
            "x_axis": "Year",
            "legend": [
              "Low-income",
              "Lower-middle-income",
              "Upper-middle-income"
            ],
            "data_trends": {
              "Low-income": "Remains above 1.0 from 2020 to 2024, showing little decline.",
              "Lower-middle-income": "Peaks in 2020 (approx. 1.15), declines to 1.0 in 2022, and continues to decline to approx. 0.9 in 2024.",
              "Upper-middle-income": "Remains at 1.0 until 2021, then drops significantly to approx. 0.8 in 2022 and continues to decline to approx. 0.78 in 2024."
            }
          },
          {
            "title": "b. Poverty at $6.85 relative to 2019 levels",
            "y_axis": "Change in poverty rates at $6.85 (2019 = 1)",
            "x_axis": "Year",
            "legend": [
              "Low-income",
              "Lower-middle-income",
              "Upper-middle-income"
            ],
            "data_trends": {
              "Low-income": "Shows a slight increase above 1.0 from 2020 to 2024.",
              "Lower-middle-income": "Remains near 1.0, with a slight decline to approx. 0.95 by 2024.",
              "Upper-middle-income": "Remains at 1.0 until 2021, then drops to approx. 0.85 in 2022 and continues to decline to approx. 0.8 in 2024."
            }
          }
        ],
        "source": "World Bank, Poverty and Inequality Platform (version September 2024), https://pip.worldbank.org/.",
        "note": "Poverty rates are shown relative to 2019 levels for the $2.15 and $6.85 per person per day poverty lines (expressed in 2017 purchasing power parity dollars). The line for low-income countries is dotted because the surveys covered less than 50 percent of the group’s population between 2019 and 2022. Poverty rates for 2022–24 are projected based on per capita gross domestic product growth projections in Global Economic Prospects, June 2024 (World Bank 2024c). High-income countries are omitted because poverty rates at both lines are small. Poverty rates at the $6.85 poverty line did not increase in high-income countries between 2019 and 2024, and changes at the $2.15 poverty line were less than 0.05 percentage points. Income group is kept fixed using the fiscal year 2024 classifications."
      }
    }
  ]
}
